import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] env = new long[(int) n][2];
        for (int i = 0; i < env.length; i++) {
            for (int j = 0; j < env[i].length; j++) {
                env[i][j] = Long.parseLong(next());
            }
        }

        long[] keys = new long[(int) n];
        for (int i = 0; i < n; i++) keys[i] = env[i][0] * 2147483648L + (1000000000L - env[i][1]);
        Arrays.sort(keys);
        long[] tails = new long[(int) n];
        int size = 0;
        for (int i = 0; i < n; i++) {
            long h = 1000000000L - (keys[i] & 2147483647L);
            int lo = 0, hi = size;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (tails[mid] < h) lo = mid + 1;
                else hi = mid;
            }
            tails[lo] = h;
            if (lo == size) size++;
        }
        System.out.println(size);
    }
}
